mapper.select:
SELECT e.LEC_STD_ENR_ID
FROM LECTURE_STUDENT_ENROLLMENT e
JOIN LECTURE l     ON l.LEC_ID     = e.LEC_ID
JOIN LMS_PROFILE p ON p.LMS_PRF_ID = e.LMS_PRF_ID
WHERE e.LEC_ID = #{lecId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}
  AND p.MEMBER_ID = #{studentMemberId}
  AND e.LEC_STD_ENR_STATUS != 'DRP'

mapper.update:
UPDATE STUDENT_ENROLLMENT_ATTENDANCE
   SET STD_ENR_ATD_STS_CODE = #{status}
 WHERE STD_ENR_ATD_ID = #{sessionId}
   AND LEC_STD_ENR_ID = #{enrollmentId}
